// Generated by scripts/generate.ts
import { component$, useComputed$, useContext, useStore, useTask$ } from '@qwik.dev/core';
import { Level2Output } from './contexts';

export default component$(() => {
  const input = useContext(Level2Output);
  const store = useStore({ a: 0, nested: { b: 0, out: 0 } });
  useTask$(({ track }) => {
    store.a = track(input) * 2;
  });
  useTask$(({ track }) => {
    store.nested.b = track(() => store.a) * 2;
  });
  useTask$(({ track }) => {
    store.nested.out = track(() => store.nested.b) * 2;
  });
  const out = useComputed$(() => store.nested.out);

  return (
    <div class="level">
      <span class="step">level 3: {out.value}</span>
      <output data-testid="result" data-done={out.value ? '' : undefined}>
        {out.value}
      </output>
    </div>
  );
});
